  <div class="page-header">
    <div class="header-left">
      <span class="page-num">4</span>
      <span class="section-title">求是苑·记录</span>
    </div>
    <div class="header-mid">
      2018年6月15日&nbsp;&nbsp;星期五
      <div class="editor-line">责任编辑:张岚&nbsp;&nbsp;联系电话:0571-88981339</div>
